// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Ensure value does not exceed contract balance and target is not zero address to avoid revert
        vm.assume(target != address(0));
        vm.assume(value <= address(c).balance);

        uint256 balanceBefore = address(c).balance;

        // Call sendMoney – should send ether to target, not msg.sender
        c.sendMoney(target, value, data);

        uint256 balanceAfter = address(c).balance;

        // General rule: balance decreases by exactly value
        assertTrue(balanceAfter == balanceBefore - value);
    }
}

